public static Map<String, List<String>> groupByLength(List<String> words) {
    return words.stream()
        .filter(w -> w != null && !w.isBlank())
        .map(String::trim)
        .collect(Collectors.groupingBy(
            w -> {
                if (w.length() <= 3) {
                    return "short";
                } else if (w.length() <= 6) {
                    return "medium";
                } else {
                    return "long";
                }
            },
            Collectors.toList()
        ));
}

public class MathUtils {
    public static <T extends Comparable<T>> T clamp(T value, T min, T max) {
        if (value.compareTo(min) < 0) {
            return min;
        }
        if (value.compareTo(max) > 0) {
            return max;
        }
        return value;
    }

    public static <T extends Number & Comparable<T>> List<T> filterRange(
            List<T> items, T lower, T upper) {
        List<T> result = new ArrayList<>();
        for (T item : items) {
            if (item.compareTo(lower) >= 0 && item.compareTo(upper) <= 0) {
                result.add(item);
            }
        }
        return Collections.unmodifiableList(result);
    }
}

public static Map<String, Long> wordFrequency(Path filePath) throws IOException {
    Map<String, Long> freq;
    try (BufferedReader reader = Files.newBufferedReader(filePath)) {
        freq = reader.lines()
            .flatMap(line -> Arrays.stream(line.split("\\s+")))
            .map(String::toLowerCase)
            .filter(word -> !word.isBlank())
            .collect(Collectors.groupingBy(
                Function.identity(),
                Collectors.counting()
            ));
    }
    freq.entrySet().stream()
        .sorted(Map.Entry.<String, Long>comparingByValue().reversed())
        .limit(10)
        .forEach(e -> System.out.printf("%s: %d%n", e.getKey(), e.getValue()));
    return freq;
}

@FunctionalInterface
public interface EventListener<T> {
    void onEvent(T event);
}

public class EventBus<T> {
    private final List<EventListener<T>> listeners = new ArrayList<>();

    public void subscribe(EventListener<T> listener) {
        Objects.requireNonNull(listener);
        listeners.add(listener);
    }

    public void unsubscribe(EventListener<T> listener) {
        listeners.remove(listener);
    }

    public void publish(T event) {
        for (EventListener<T> listener : listeners) {
            try {
                listener.onEvent(event);
            } catch (Exception e) {
                System.err.println("Listener failed: " + e.getMessage());
            }
        }
    }
}

