public class HttpRequest {
    private final String method;
    private final String url;
    private final Map<String, String> headers;
    private final String body;

    private HttpRequest(Builder builder) {
        this.method = builder.method;
        this.url = builder.url;
        this.headers = Collections.unmodifiableMap(builder.headers);
        this.body = builder.body;
    }

    public static class Builder {
        private String method = "GET";
        private String url;
        private final Map<String, String> headers = new LinkedHashMap<>();
        private String body;

        public Builder url(String url) {
            this.url = Objects.requireNonNull(url, "URL must not be null");
            return this;
        }

        public Builder method(String method) {
            this.method = Objects.requireNonNull(method);
            return this;
        }

        public Builder header(String key, String value) {
            headers.put(
                Objects.requireNonNull(key),
                Objects.requireNonNull(value)
            );
            return this;
        }

        public Builder body(String body) {
            this.body = body;
            return this;
        }

        public HttpRequest build() {
            if (url == null || url.isBlank()) {
                throw new IllegalStateException("URL is required");
            }
            return new HttpRequest(this);
        }
    }
}

public class SimpleCache<K, V> {
    private final Map<K, V> store = new LinkedHashMap<>();
    private final ReadWriteLock lock = new ReentrantReadWriteLock();
    private final int maxSize;

    public SimpleCache(int maxSize) {
        this.maxSize = maxSize;
    }

    public V get(K key) {
        lock.readLock().lock();
        try {
            return store.get(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public void put(K key, V value) {
        lock.writeLock().lock();
        try {
            if (store.size() >= maxSize) {
                Iterator<K> it = store.keySet().iterator();
                if (it.hasNext()) {
                    it.next();
                    it.remove();
                }
            }
            store.put(key, value);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public int size() {
        lock.readLock().lock();
        try {
            return store.size();
        } finally {
            lock.readLock().unlock();
        }
    }
}

public class Statistics {
    private final long count;
    private final double sum;
    private final double min;
    private final double max;

    private Statistics(long count, double sum, double min, double max) {
        this.count = count;
        this.sum = sum;
        this.min = min;
        this.max = max;
    }

    public double average() {
        return count > 0 ? sum / count : 0.0;
    }

    public static Collector<Double, ?, Statistics> collector() {
        return Collector.of(
            () -> new double[]{0, 0, Double.MAX_VALUE, Double.MIN_VALUE},
            (acc, val) -> {
                acc[0]++;
                acc[1] += val;
                acc[2] = Math.min(acc[2], val);
                acc[3] = Math.max(acc[3], val);
            },
            (a, b) -> {
                a[0] += b[0];
                a[1] += b[1];
                a[2] = Math.min(a[2], b[2]);
                a[3] = Math.max(a[3], b[3]);
                return a;
            },
            acc -> new Statistics((long) acc[0], acc[1], acc[2], acc[3])
        );
    }
}

