@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.FIELD)
public @interface JsonField {
    String value() default "";
}

public class JsonSerializer {
    public static String serialize(Object obj) {
        StringBuilder sb = new StringBuilder("{");
        Field[] fields = obj.getClass().getDeclaredFields();
        boolean first = true;
        for (Field field : fields) {
            JsonField ann = field.getAnnotation(JsonField.class);
            if (ann != null) {
                field.setAccessible(true);
                if (!first) {
                    sb.append(", ");
                }
                String key = ann.value().isEmpty()
                    ? field.getName()
                    : ann.value();
                try {
                    Object val = field.get(obj);
                    sb.append(String.format("\"%s\": \"%s\"", key, val));
                } catch (IllegalAccessException e) {
                    throw new RuntimeException(e);
                }
                first = false;
            }
        }
        sb.append("}");
        return sb.toString();
    }
}

public class AsyncPipeline {
    private final ExecutorService executor;
    private final HttpClient client;

    public AsyncPipeline(ExecutorService executor, HttpClient client) {
        this.executor = executor;
        this.client = client;
    }

    public CompletableFuture<Map<String, Object>> fetchAndProcess(List<String> urls) {
        List<CompletableFuture<String>> futures = urls.stream()
            .map(url -> CompletableFuture.supplyAsync(() -> {
                try {
                    HttpRequest req = HttpRequest.newBuilder()
                        .uri(URI.create(url))
                        .timeout(Duration.ofSeconds(10))
                        .GET()
                        .build();
                    HttpResponse<String> resp = client.send(
                        req, HttpResponse.BodyHandlers.ofString()
                    );
                    if (resp.statusCode() != 200) {
                        throw new RuntimeException(
                            "HTTP " + resp.statusCode() + " for " + url
                        );
                    }
                    return resp.body();
                } catch (IOException | InterruptedException e) {
                    throw new CompletionException(e);
                }
            }, executor))
            .toList();

        return CompletableFuture.allOf(futures.toArray(CompletableFuture[]::new))
            .thenApply(v -> {
                Map<String, Object> results = new LinkedHashMap<>();
                for (int i = 0; i < urls.size(); i++) {
                    try {
                        results.put(urls.get(i), futures.get(i).join());
                    } catch (CompletionException e) {
                        results.put(urls.get(i), e.getCause().getMessage());
                    }
                }
                return Collections.unmodifiableMap(results);
            });
    }
}

public interface Specification<T> {
    boolean isSatisfiedBy(T item);

    default Specification<T> and(Specification<T> other) {
        return item -> this.isSatisfiedBy(item) && other.isSatisfiedBy(item);
    }

    default Specification<T> or(Specification<T> other) {
        return item -> this.isSatisfiedBy(item) || other.isSatisfiedBy(item);
    }

    default Specification<T> not() {
        return item -> !this.isSatisfiedBy(item);
    }
}

public class InMemoryRepository<T> {
    private final List<T> items = new ArrayList<>();

    public void add(T item) {
        Objects.requireNonNull(item);
        items.add(item);
    }

    public List<T> findAll(Specification<T> spec) {
        return items.stream()
            .filter(spec::isSatisfiedBy)
            .collect(Collectors.toUnmodifiableList());
    }

    public Optional<T> findFirst(Specification<T> spec) {
        return items.stream()
            .filter(spec::isSatisfiedBy)
            .findFirst();
    }

    public long count(Specification<T> spec) {
        return items.stream()
            .filter(spec::isSatisfiedBy)
            .count();
    }

    public <R extends Comparable<R>> List<T> findSorted(
            Specification<T> spec, Function<T, R> keyExtractor) {
        return items.stream()
            .filter(spec::isSatisfiedBy)
            .sorted(Comparator.comparing(keyExtractor))
            .collect(Collectors.toUnmodifiableList());
    }
}

public sealed interface Expr {
    record Num(double value) implements Expr {}
    record Add(Expr left, Expr right) implements Expr {}
    record Mul(Expr left, Expr right) implements Expr {}
    record Neg(Expr operand) implements Expr {}
    record Let(String name, Expr value, Expr body) implements Expr {}
}

public class ExprEvaluator {
    public static double eval(Expr expr, Map<String, Double> env) {
        return switch (expr) {
            case Expr.Num n -> n.value();
            case Expr.Add a -> eval(a.left(), env) + eval(a.right(), env);
            case Expr.Mul m -> eval(m.left(), env) * eval(m.right(), env);
            case Expr.Neg n -> -eval(n.operand(), env);
            case Expr.Let l -> {
                double val = eval(l.value(), env);
                Map<String, Double> newEnv = new HashMap<>(env);
                newEnv.put(l.name(), val);
                yield eval(l.body(), newEnv);
            }
        };
    }

    public static String prettyPrint(Expr expr) {
        return switch (expr) {
            case Expr.Num n -> String.valueOf(n.value());
            case Expr.Add a -> String.format(
                "(%s + %s)", prettyPrint(a.left()), prettyPrint(a.right())
            );
            case Expr.Mul m -> String.format(
                "(%s * %s)", prettyPrint(m.left()), prettyPrint(m.right())
            );
            case Expr.Neg n -> String.format(
                "(-%s)", prettyPrint(n.operand())
            );
            case Expr.Let l -> String.format(
                "let %s = %s in %s",
                l.name(), prettyPrint(l.value()), prettyPrint(l.body())
            );
        };
    }
}

public class TypedEventBus {
    private final Map<Class<?>, List<Consumer<?>>> handlers =
        new ConcurrentHashMap<>();

    public <T> void subscribe(Class<T> eventType, Consumer<T> handler) {
        handlers.computeIfAbsent(eventType, k -> new CopyOnWriteArrayList<>())
            .add(handler);
    }

    @SuppressWarnings("unchecked")
    public <T> void publish(T event) {
        Objects.requireNonNull(event);
        Class<?> type = event.getClass();
        while (type != null) {
            List<Consumer<?>> consumers = handlers.get(type);
            if (consumers != null) {
                for (Consumer<?> consumer : consumers) {
                    try {
                        ((Consumer<T>) consumer).accept(event);
                    } catch (ClassCastException e) {
                        System.err.printf(
                            "Handler cast failed for %s: %s%n",
                            type.getSimpleName(), e.getMessage()
                        );
                    }
                }
            }
            for (Class<?> iface : type.getInterfaces()) {
                List<Consumer<?>> ifaceHandlers = handlers.get(iface);
                if (ifaceHandlers != null) {
                    for (Consumer<?> consumer : ifaceHandlers) {
                        try {
                            ((Consumer<T>) consumer).accept(event);
                        } catch (ClassCastException e) {
                            System.err.printf(
                                "Interface handler failed for %s: %s%n",
                                iface.getSimpleName(), e.getMessage()
                            );
                        }
                    }
                }
            }
            type = type.getSuperclass();
        }
    }

    public void clear() {
        handlers.clear();
    }
}

public class QueryBuilder<T> {
    private final List<T> source;
    private final List<Predicate<T>> filters = new ArrayList<>();
    private Comparator<T> ordering;
    private int offset = 0;
    private int limit = Integer.MAX_VALUE;

    private QueryBuilder(List<T> source) {
        this.source = Objects.requireNonNull(source);
    }

    public static <T> QueryBuilder<T> from(List<T> source) {
        return new QueryBuilder<>(source);
    }

    public QueryBuilder<T> where(Predicate<T> predicate) {
        filters.add(Objects.requireNonNull(predicate));
        return this;
    }

    public <U extends Comparable<U>> QueryBuilder<T> orderBy(
            Function<T, U> keyExtractor) {
        this.ordering = Comparator.comparing(keyExtractor);
        return this;
    }

    public QueryBuilder<T> skip(int count) {
        this.offset = Math.max(0, count);
        return this;
    }

    public QueryBuilder<T> take(int count) {
        this.limit = Math.max(0, count);
        return this;
    }

    public List<T> execute() {
        Stream<T> pipeline = source.stream();
        for (Predicate<T> filter : filters) {
            pipeline = pipeline.filter(filter);
        }
        if (ordering != null) {
            pipeline = pipeline.sorted(ordering);
        }
        return pipeline
            .skip(offset)
            .limit(limit)
            .collect(Collectors.toUnmodifiableList());
    }

    public <R> List<R> select(Function<T, R> mapper) {
        Stream<T> pipeline = source.stream();
        for (Predicate<T> filter : filters) {
            pipeline = pipeline.filter(filter);
        }
        if (ordering != null) {
            pipeline = pipeline.sorted(ordering);
        }
        return pipeline
            .skip(offset)
            .limit(limit)
            .map(mapper)
            .collect(Collectors.toUnmodifiableList());
    }
}
